using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Analytic.GaussZeroBalanced;

internal sealed class SeriesDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Positive Gauss series and the Riccati equation", H("Series identities"), Blocks(
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-coefficient-pos"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.coefficient_pos"),
                H("Positive hypergeometric coefficients"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive real a, b and c and every natural n, ordinaryHypergeometricCoefficient a b c n is strictly positive. The factorial and ascending Pochhammer factors are positive."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-coefficient-recurrence"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.coefficient_recurrence"),
                H("The coefficient recurrence"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For all real a and b, positive real c and natural n, write h(n)=ordinaryHypergeometricCoefficient a b c n. Then (n+1)h(n+1)(c+n)=(a+n)(b+n)h(n). With b=1-a and c=1 this supplies the normalized elliptic coefficient recurrence."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-one-le-gauss"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.one_le_gauss"),
                H("Lower bound by the constant term"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive real a, b and c and 0 <= x < 1, gauss a b c x is at least one. All coefficients and all terms are nonnegative, and the constant term is one."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-gauss-pos"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.gauss_pos"),
                H("Positivity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive real a, b and c and 0 <= x < 1, gauss a b c x is strictly positive."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-hasderivat-gauss"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.hasDerivAt_gauss"),
                H("Differentiation in the argument"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive real a, b and c and 0 <= x < 1, the derivative of gauss a b c at x is (a*b/c) times gauss (a+1) (b+1) (c+1) x. At zero this is a two-sided derivative. A radius strictly between abs(x) and one supplies a summable majorant for the termwise derivatives."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-contiguous-g"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.contiguous_G"),
                H("The denominator-parameter shift"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0 <= x < 1, put c=a+b, H(x)=gauss a b c x, and G(x)=gauss a b (c+1) x. Then x times the derivative of G is c(H-G). The coefficient relation is (c+n)G[n]=cH[n]."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-contiguous-h"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.contiguous_H"),
                H("The zero-balanced derivative identity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0 <= x < 1, put c=a+b, H(x)=gauss a b c x, and G(x)=gauss a b (c+1) x. Then (1-x) times the derivative of H is (ab/c)G. The coefficient recurrence cancels the remaining terms because c=a+b."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-f-zero"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.f_zero"),
                H("The origin value"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every real a and b, f a b 0 equals one."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-f-pos"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.f_pos"),
                H("The positive contiguous quotient"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0 <= x < 1, f a b x is positive."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-f-lt-one"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.f_lt_one"),
                H("The strict upper bound"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0 < x < 1, f a b x is less than one. The first contiguous identity and the positive derivative of G give G(x)<H(x)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-hasderivat-f"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.hasDerivAt_f"),
                H("The quotient derivative"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0 <= x < 1, with c=a+b, H(x)=gauss a b c x and G(x)=gauss a b (c+1) x, the function f a b has derivative (deriv(G,x)H(x)-G(x)deriv(H,x))/H(x)^2 at x. Positivity of H justifies the quotient rule, including at zero."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-continuouson-f"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.continuousOn_f"),
                H("Continuity including the origin"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b, f a b is continuous on the half-closed interval [0,1)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-quot-eq"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.quot_eq"),
                H("The relation between the quotients"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0 <= x < 1, quot a b x equals f a b x divided by 1-x. The derivative identity cancels the positive factor ab/(a+b)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-riccati"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.riccati"),
                H("The Riccati equation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0 < x < 1, put c=a+b. The function f satisfies x deriv(f,x)=c(1-f(x))-(ab/c)(x/(1-x))f(x)^2. Both contiguous identities enter the quotient rule; positivity of the denominator permits the algebraic cancellations."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-deriv-f-zero"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/Series.deriv_f_zero"),
                H("The initial slope"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b, the derivative of f a b at zero is -ab/((a+b)(a+b+1)). This follows by evaluating the quotient rule at the series origin."))), DescribeRole.Theorem))));
}
